fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut rev_chars = txt.chars().rev();

    // Get the last character
    match rev_chars.next() {
        // It must be an ASCII alphabetic letter
        Some(last) if last.is_ascii_alphabetic() => {
            // If there is a preceding character, it must be a space.
            match rev_chars.next() {
                Some(prev) => prev == ' ',
                None => true, // No preceding character => single‐character string
            }
        }
        _ => false, // Empty string or last char not ASCII letter
    }
}

